def fill_line_gaps(grid, fill=2):
    """Fill background cells on the bounding-box border of all marks and on straight lines through interior same-colored marks (marks kept)."""
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(H) for c in range(W) if grid[r][c] != bg]
    # 1. interior collinear marks: same color, same row or col, only bg between them
    for color in cnt:
        if color == bg: continue
        cps = [p for p in pts if grid[p[0]][p[1]] == color]
        byc = {}
        for r, c in cps: byc.setdefault(c, []).append(r)
        for c, rs in byc.items():
            rs = sorted(rs)
            for a, b in zip(rs, rs[1:]):
                if all(grid[m][c] == bg for m in range(a+1, b)):
                    for m in range(a+1, b): out[m][c] = fill
        byr = {}
        for r, c in cps: byr.setdefault(r, []).append(c)
        for r, cs2 in byr.items():
            cs2 = sorted(cs2)
            for a, b in zip(cs2, cs2[1:]):
                if all(grid[r][m] == bg for m in range(a+1, b)):
                    for m in range(a+1, b): out[r][m] = fill
    # 2. bounding-box border gaps
    r0 = min(p[0] for p in pts); r1 = max(p[0] for p in pts)
    c0 = min(p[1] for p in pts); c1 = max(p[1] for p in pts)
    for r in range(r0, r1+1):
        for c in range(c0, c1+1):
            if (r in (r0, r1) or c in (c0, c1)) and out[r][c] == bg:
                out[r][c] = fill
    return out

